# Build.ps1
# Concatenates the modular files (Main/, Sidebar/, Core/) in the correct order
# and generates the final SETTDash.ps1 (used as ps2exe input).
# DO NOT edit SETTDash.ps1 directly - it is generated by this script.

$ErrorActionPreference = "Stop"
$root = $PSScriptRoot

# Load order (dependencies must come before whoever uses them):
#   1. Main/Layout.ps1            - visual definition (XAML) of the dashboard
#   1a. Core/Embed/EmbeddedProgramsCore.ps1 - initializes $Script:EmbeddedPrograms and Extract-EmbeddedPrograms
#   1a. Core/Embed/Programs/*.ps1           - one file per embedded binary (base64/GZip)
#   1b. Main/Window.ps1            - initial setup, XAML parser (defines $Window, $txtLog, $Script:TempDir)
#   1c. Core/Embed/Fonts/EmbeddedMonospaceFont.ps1 - embedded monospace font (base64/GZip), depends on $Window/$txtLog/$Script:TempDir
#   2. Core/Helpers/*.ps1          - GUI helpers, split by domain (log, nav, metrics, cards, registry)
#   3. Core/Actions/*.ps1          - Invoke-*/Get-* action functions, split by domain
#   4. Core/Gauges/GuiGauges.ps1   - metric bar / circular gauge builders (used by Home)
#   6. Sidebar/Pages/*.ps1         - one Show-Page* function per file
#   7. Sidebar/Sidebar.ps1         - sidebar wiring (navigation and accordion)
#   8. Main/TitleBar.ps1           - custom title bar events (close/min/max/drag)
#   9. Main/Startup.ps1            - application startup
$parts = @(
    "Main\Layout.ps1",
    "Core\Embed\EmbeddedProgramsCore.ps1",
    "Core\Embed\Programs\Autoruns64.exe.ps1",
    "Core\Embed\Programs\DeviceCleanup.exe.ps1",
    "Core\Embed\Programs\DnsJumper.exe.ps1",
    "Core\Embed\Programs\FilterKeysSetter.exe.ps1",
    "Core\Embed\Programs\MSI_util_v3.exe.ps1",
    "Core\Embed\Programs\OOAPB.exe.ps1",
    "Core\Embed\Programs\SETTMemoryCleaner.exe.ps1",
    "Core\Embed\Programs\TimerResolution.exe.ps1",
    "Core\Embed\Programs\sPowers_x64.exe.ps1",
    "Core\Embed\Programs\settPowerPlan.pow.ps1",
    "Core\Embed\Programs\vibranceGUI.exe.ps1",
    "Main\Window.ps1",
    "Core\Embed\Fonts\EmbeddedMonospaceFont.ps1",
    "Core\Helpers\Log.ps1",
    "Core\Helpers\Navigation.ps1",
    "Core\Helpers\Metrics.ps1",
    "Core\Helpers\Cards.ps1",
    "Core\Helpers\RegistryHelpers.ps1",
    "Core\Helpers\FileCleanup.ps1",
    "Core\Helpers\InstallHelpers.ps1",
    "Core\Helpers\UpdateChecker.ps1",
    "Core\Actions\Utilities.ps1",
    "Core\Actions\NetworkPrivacy\InternetQoS.ps1",
    "Core\Actions\NetworkPrivacy\PrivacySettings.ps1",
    "Core\Actions\NetworkPrivacy\Integrations.ps1",
    "Core\Actions\SystemTweaksAll\SystemTweaks.ps1",
    "Core\Actions\SystemTweaksAll\Services.ps1",
    "Core\Actions\Windows\ContextMenuW11.ps1",
    "Core\Actions\Windows\Browsers.ps1",
    "Core\Actions\Windows\ContextMenu.ps1",
    "Core\Actions\Performance\PowerPlan.ps1",
    "Core\Actions\Performance\GameMode.ps1",
    "Core\Actions\Performance\GameExtra.ps1",
    "Core\Actions\Performance\Memory.ps1",
    "Core\Actions\Performance\GPU.ps1",
    "Core\Actions\Home\RestorePoint.ps1",
    "Core\Actions\Home\SystemInfo.ps1",
    "Core\Actions\Home\NetworkOptimizer.ps1",
    "Core\Actions\Home\NetworkTools.ps1",
    "Core\Actions\Home\CacheCleaner\TempFiles.ps1",
    "Core\Actions\Home\CacheCleaner\BrowserCache.ps1",
    "Core\Actions\Home\CacheCleaner\UpdateCache.ps1",
    "Core\Actions\Home\CacheCleaner\Prefetch.ps1",
    "Core\Actions\Home\CacheCleaner\StoreCache.ps1",
    "Core\Actions\Home\CacheCleaner\LogFiles.ps1",
    "Core\Actions\Home\CacheCleaner\MemoryDumps.ps1",
    "Core\Actions\Home\CacheCleaner\DeliveryOpt.ps1",
    "Core\Actions\Home\CacheCleaner\ShaderCache.ps1",
    "Core\Actions\Home\CacheCleaner\FullCleanup.ps1",
    "Core\Actions\Playbooks.ps1",
    "Core\Actions\FullAutoOptimize.ps1",
    "Core\Helpers\CleanList.ps1",
    "Core\Actions\Clean\SystemCleanerScan.ps1",
    "Core\Actions\Clean\RegistryCleanerScan.ps1",
    "Core\Actions\Clean\StartupManagerScan.ps1",
    "Core\Actions\Clean\NetworkCleanupScan.ps1",
    "Core\Gauges\GuiGauges.ps1",
    "Sidebar\Pages\Home.ps1",
    "Sidebar\Pages\Installers.ps1",
    "Sidebar\Pages\AllInstallers.ps1",
    "Sidebar\Pages\GpuSoftware.ps1",
    "Sidebar\Pages\CPU.ps1",
    "Sidebar\Pages\Performance.ps1",
    "Sidebar\Pages\NetworkPrivacy.ps1",
    "Sidebar\Pages\SystemTweaksAll.ps1",
    "Sidebar\Pages\Windows.ps1",
    "Sidebar\Pages\Utilities.ps1",
    "Sidebar\Pages\WinShortcuts.ps1",
    "Sidebar\Pages\Playbooks.ps1",
    "Sidebar\Pages\All.ps1",
    "Sidebar\Pages\Clean.ps1",
    "Sidebar\Pages\Network.ps1",
    "Sidebar\Sidebar.ps1",
    "Main\TitleBar.ps1",
    "Main\Startup.ps1"
)

$output = foreach ($part in $parts) {
    $path = Join-Path $root $part
    if (-not (Test-Path $path)) { throw "File not found: $path" }
    Get-Content -Path $path -Encoding UTF8
}

$outFile = Join-Path $root "SETTDash.ps1"
$output | Set-Content -Path $outFile -Encoding UTF8

Write-Host "SETTDash.ps1 generated successfully ($($output.Count) lines)." -ForegroundColor Green
